<?php
$saE=static fn($v)=>htmlspecialchars((string)($v??''),ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');
$saLabel=static fn($v)=>ucwords(str_replace('_',' ',(string)$v));
$saDate=static function($v,$format='M j, Y'){return $v&&strtotime($v)!==false?date($format,strtotime($v)):'Not provided';};
$saStatuses=['pending'=>'Pending','confirmed'=>'Confirmed','in_progress'=>'In progress','completed'=>'Completed','cancelled'=>'Cancelled','missed'=>'Missed','rescheduled'=>'Rescheduled'];
$saConcerns=['academic'=>'Academic','personal'=>'Personal','behavioral'=>'Behavioral','career'=>'Career guidance','family'=>'Family concerns','other'=>'Other'];
$saMessages=['pending'=>'Your request is awaiting confirmation. You will be notified when it is confirmed.','confirmed'=>'Your appointment is confirmed. Please arrive 10 minutes before your scheduled time.','in_progress'=>'Your counseling session is in progress.','completed'=>'Your counseling session has been completed.','cancelled'=>'This appointment was cancelled.','missed'=>'This appointment was marked as missed. Contact the guidance office if you need assistance.','rescheduled'=>'This appointment was rescheduled. Check your latest appointment for the updated date and time.'];
$saToday=date('Y-m-d');$saCounts=['all'=>count($appointments),'upcoming'=>0,'completed'=>0,'closed'=>0];$saData=[];$saNext=null;
foreach($appointments as $a){
 $state=(string)$a['status'];$date=(string)$a['appointment_date'];$upcoming=in_array($state,['pending','confirmed','in_progress'],true)&&$date>=$saToday;
 if($upcoming){$saCounts['upcoming']++;if(!$saNext||$date.' '.$a['appointment_time']<$saNext['appointment_date'].' '.$saNext['appointment_time'])$saNext=$a;}
 if($state==='completed')$saCounts['completed']++;if(in_array($state,['cancelled','missed'],true))$saCounts['closed']++;
 $counselor=trim((string)($a['assigned_advocate_name']??''));$counselor=$counselor!==''?$counselor:($state==='confirmed'||$state==='pending'?'Awaiting assignment':'Not assigned');
 $concern=$saConcerns[$a['concern_type']??'']??($saLabel($a['concern_type']??'')?:'Not provided');
 $description=trim((string)($a['concern_description']??''));if($description==='individual')$description='';
 $saData[(string)$a['id']]=['id'=>(int)$a['id'],'date'=>$date,'dateLabel'=>$saDate($date,'l, F j, Y'),'time'=>$saDate($a['appointment_time'],'g:i A'),'status'=>$state,'statusLabel'=>$saStatuses[$state]??$saLabel($state),'upcoming'=>$upcoming,'concern'=>$concern,'description'=>$description,'urgency'=>$saLabel($a['urgency_level']??'')?:'Not provided','counselor'=>$counselor,'message'=>$saMessages[$state]??'Contact the guidance office for information about this appointment.','followUp'=>!empty($a['is_follow_up']),'original'=>!empty($a['original_appointment_id'])&&!empty($a['original_date'])?$saDate($a['original_date'],'F j, Y').' at '.$saDate($a['original_time']??'','g:i A'):'','submitted'=>$saDate($a['created_at']??'','M j, Y · g:i A'),'confirmed'=>!empty($a['confirmed_at'])?$saDate($a['confirmed_at'],'M j, Y · g:i A'):'','canCancel'=>in_array($state,['pending','confirmed','in_progress'],true)&&empty($a['assigned_advocate_id'])];
}
$saEnabled=$settings->isCounselingEnabled();
