 <?php if($success_message):?><p class="sa-feedback" role="status"><?=$saE($success_message)?></p><?php endif;?><?php if($error_message):?><p class="sa-feedback sa-feedback-error" role="alert"><?=$saE($error_message)?></p><?php endif;?>
 <div class="sa-summary" role="group" aria-label="Filter appointments by status">
 <?php foreach(['all'=>['All appointments','Your complete history','▦'],'upcoming'=>['Upcoming','Today and future sessions','◷'],'completed'=>['Completed','Finished sessions','✓'],'closed'=>['Cancelled & missed','Previous appointments','⊘']] as $key=>$item):?>
 <button type="button" class="sa-stat" data-sa-filter="<?=$key?>" aria-pressed="<?=$key==='all'?'true':'false'?>"><span class="sa-stat-icon sa-tone-<?=$key?>" aria-hidden="true"><?=$item[2]?></span><span><strong><?=$saCounts[$key]?></strong><span><?=$item[0]?></span><small><?=$item[1]?></small></span><span class="sa-stat-arrow" aria-hidden="true">›</span></button>
 <?php endforeach;?></div>
 <?php if($saNext):$next=$saData[(string)$saNext['id']];?><aside class="sa-next" aria-labelledby="saNextTitle"><span class="sa-next-icon" aria-hidden="true">◷</span><div><p class="sa-eyebrow" id="saNextTitle">YOUR NEXT APPOINTMENT</p><h2><?=$saE($next['dateLabel'])?> <span>· <?=$saE($next['time'])?></span></h2><p><?=$saE($next['concern'])?> <span aria-hidden="true">·</span> <?=$saE($next['counselor'])?></p></div><button type="button" class="sa-button" data-sa-details="<?=$next['id']?>">View details <span aria-hidden="true">→</span></button></aside><?php endif;?>
 <details class="sa-filters"><summary><span>Filters <small id="saFilterCount"></small></span><small>Find a session by date, status or concern</small></summary><div class="sa-filter-grid"><label for="saSearch">Search appointments<input type="search" id="saSearch" placeholder="Search concern, counselor or date" autocomplete="off"></label><label for="saStatus">Status<select id="saStatus"><option value="all">All appointments</option><option value="upcoming">Upcoming</option><?php foreach($saStatuses as $value=>$label):?><option value="<?=$value?>"><?=$label?></option><?php endforeach;?><option value="closed">Cancelled &amp; missed</option></select></label><label for="saFrom">From date<input type="date" id="saFrom"></label><label for="saTo">To date<input type="date" id="saTo"></label><button type="button" class="sa-button" id="saClear">Clear filters</button></div><p id="saDateError" role="alert" class="sa-date-error" hidden>Choose an end date on or after the start date.</p></details>
 <div class="sa-results-heading"><div><h2>Appointment history</h2><p id="saScope" role="status" aria-live="polite">All appointments</p></div><span class="sa-private">Only your appointments are shown</span></div>
 <div class="sa-list" id="saList">
 <?php $saRowIndex=0;foreach($appointments as $a):$item=$saData[(string)$a['id']];?>
 <article class="sa-row" <?=$saRowIndex++>=10?'hidden':''?> data-sa-row="<?=$item['id']?>" aria-label="<?=$saE($item['concern'].' appointment, '.$item['dateLabel'].', '.$item['statusLabel'])?>">
 <div class="sa-date-stamp" aria-hidden="true"><span><?=$saE($saDate($item['date'],'M'))?></span><strong><?=$saE($saDate($item['date'],'j'))?></strong><small><?=$saE($saDate($item['date'],'Y'))?></small></div>
 <div class="sa-row-main"><div class="sa-row-title"><h3><?=$saE($item['concern'])?> counseling</h3><?php if($item['followUp']):?><span class="sa-followup">Follow-up</span><?php endif;?></div><p class="sa-row-time"><?=$saE($saDate($item['date'],'D, M j, Y'))?> <span aria-hidden="true">·</span> <?=$saE($item['time'])?></p><p class="sa-description"><?=$saE($item['description']?:'No concern description provided.')?></p></div>
 <dl class="sa-row-counselor"><dt>Counselor</dt><dd><?=$saE($item['counselor'])?></dd></dl>
 <div class="sa-row-action"><span class="sa-badge" data-sa-status="<?=$saE($item['status'])?>"><?=$saE($item['statusLabel'])?></span><button type="button" class="sa-details-button" data-sa-details="<?=$item['id']?>" aria-label="<?=$saE('View '.$item['concern'].' appointment on '.$item['dateLabel'])?>">View details <span aria-hidden="true">→</span></button></div>
 </article><?php endforeach;?></div>
 <div class="sa-empty" id="saEmpty" <?=$appointments?'hidden':''?>><span aria-hidden="true">▦</span><h3 id="saEmptyTitle"><?=$appointments?'No matching appointments':'No appointments yet'?></h3><p id="saEmptyText"><?=$appointments?'Try a different status, date range or search.':'When you book a counseling session, it will appear here.'?></p><button type="button" class="sa-button" id="saEmptyClear" <?=$appointments?'':'hidden'?>>Clear filters</button><?php if(!$appointments&&$saEnabled):?><a href="<?=$saE($book_url)?>" class="sa-button sa-primary">Book your first appointment</a><?php endif;?></div>
 <footer class="sa-pagination" id="saPagination" <?=$appointments?'':'hidden'?>><p id="saPageInfo">Showing <?=$appointments?1:0?>–<?=min(10,count($appointments))?> of <?=count($appointments)?> appointments</p><nav aria-label="Appointment history pages"><button type="button" class="sa-button" id="saPrev" disabled>← Previous</button><span id="saPageNumber">Page 1 of <?=max(1,(int)ceil(count($appointments)/10))?></span><button type="button" class="sa-button" id="saNext" <?=count($appointments)<=10?'disabled':''?>>Next →</button></nav></footer>
